for t in range(5):
    model.addConstr(NumHeifers[t] >= 0, name=f"NonNegHeifers_{t}")
    model.addConstr(NumCows[t] >= 0, name=f"NonNegCows_{t}")

for t in range(5):
    if t == 0:
        prev_heifers = NHeifers
    else:
        prev_heifers = NumHeifers[t-1]
    model.addConstr(NumHeifers[t] == (1 - LossHeifer) * (prev_heifers - SellHeifer[t]) + 0.5 * CowCalve * NumCows[t], name=f"HeiferBalance_{t}")

for t in range(5):
    if t == 0:
        model.addConstr(NumCows[t] == (1 - LossCow) * NMilk, name=f"CowBalance_{t}")
    else:
        model.addConstr(NumCows[t] == (1 - LossCow) * NumCows[t-1], name=f"CowBalance_{t}")

total_grain_yield = sum(GrainYield[g] * GrainDivision[g] for g in range(NumGrainDivisions))
for t in range(5):
    model.addConstr(total_grain_yield * SpaceGrainUsed[t] / SpaceGrain + BuyGrain[t] >= CowGrain * NumCows[t] + SellGrain[t], name=f"GrainBalance_{t}")

for t in range(5):
    model.addConstr(NumExtraCow[t] >= NumCows[t] - NMaxCow, name=f"ExtraCow_{t}")
    model.addConstr(NumExtraCow[t] >= 0, name=f"NonNegExtraCow_{t}")
